INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('ng-su2-bluestorm-submarine', 'Tethered Anti-Aircraft Pod', 80, 'Small target: Called Shot, -4 to strike.', 3),
  ('ng-su2-bluestorm-submarine', 'Dive Planes (4)', 100, 'Each. More than one lost: torpedoes at it are +1 to strike and diving takes twice as long, one minute.', 4),
  ('ng-su2-bluestorm-submarine', 'Sensor Periscope', 80, 'Small target: Called Shot, -4 to strike.', 5),
  ('ng-su2-bluestorm-submarine', 'Main Body', 300, 'Reduced to zero, the vehicle shuts down completely and is useless; in the water it sinks within 4D6 minutes.', 6);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-amp-007-alligator-apc', 1, 'AM-7 Mini-Missile Launcher', 'By mini-missile type; fragmentation (5D6 M.D.), high explosive (1D4x10 M.D.) and plasma (1D6x10 M.D.) are the most common', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 6; a single missile or a volley is one melee attack', '36. Another 36 fit an internal container and are hand-loaded from outside: 2-3 minutes for a practised two-man team, 8-10 for a green or frightened one', NULL, 'Standard. A rapid-fire box launcher in a top turret turning 360 degrees with a 45 degree up and down arc, fired by the pilot, the gunner or a passenger. Mini-torpedoes can be loaded, though it is kept mostly for land and surface targets.'),
  ('ng-amp-007-alligator-apc', 2, 'Hatch Laser', '4D6 M.D.; 1D4x10 M.D. per 40-round burst when the NG-202 rail gun is fitted instead', 1, 'Laser 3,000 ft (914 m); rail gun 4,000 ft (1,219 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 60 shots per charge on electric battery. The rail gun: 100 bursts from a 4,000-round drum', NULL, 'Standard. A heavy laser in front of the roof hatch, worked like a tank''s manned machine-gun, turning 360 degrees with a 90 degree up and down arc. An NG-202 rail gun (gear row ng-202-rail-gun) can replace it to fire hard rounds, anti-vampire and anti-monster ammunition included.'),
  ('ng-amp-007-alligator-apc', 3, 'Smoke Grenade Dispensers (2)', 'Smoke: a 50x50 ft (15x15 m) screen from 2 grenades, 100x100 ft (30.5 x 30.5 m) from 4; shooting into or out of it is -10 to strike man-sized targets and -6 against large vehicles. Fragmentation: 3D6 M.D. to a 12 ft (3.6 m) radius, 5D6 M.D. to 24 ft (7.3 m) for two, 1D6x10 M.D. to 40 ft (12.2 m) for four', 1, 'About 100 ft (30.5 m) in front of the vehicle', 'Patterns of two or four grenades', '8; four per dispenser', NULL, 'Standard. Mounted on top toward the rear, to hide a landing, cover the troops getting out and let the APC withdraw.'),
  ('ng-aqua-212-aquapod', 1, 'NG-0212 Blue-Green Heavy Laser Turret', '5D6 M.D. per blast; 1D6x10 M.D. when two turrets fire together at one target', 1, '2,000 ft (610 m)', 'Each single or dual blast is one melee attack', 'Effectively unlimited', NULL, 'Aquapod, standard: one turret off to one side of the nose; a second on the other side costs 500,000 credits, and the pair fire separately or together. Turns 360 degrees with a 45 degree up and down arc and fires above or below the water; usually worked by the gunner or the co-pilot.'),
  ('ng-aqua-212-aquapod', 2, 'Mini-Missile Pop-Up Launchers (2)', 'By mini-missile type; standard issue is 45% high explosive (1D4x10 M.D.), 45% plasma (1D6x10 M.D.) and 10% smoke', 1, 'One mile (1.6 km)', 'One at a time or volleys of two, four or six', '36; eighteen in each wing', NULL, 'Aquapod, standard: one pop-up launcher in each forward wing, turning 360 degrees with a 90 degree upward arc. Mini-missiles only, never torpedoes.'),
  ('ng-aqua-212-aquapod', 3, 'Mini-Sub: Blue-Green Light Laser Mini-Turret', '3D6 M.D. per blast (the entry prints 3D6 per blast)', 1, '1,600 ft (488 m)', 'Each blast is one melee attack', 'Effectively unlimited', NULL, 'Mini-sub weapon 1. Hardly more than a barrel in a turret housing, turning 360 degrees with a 20 degree up and down arc; fires above or below the water.'),
  ('ng-aqua-212-aquapod', 4, 'Mini-Sub: Mini-Torpedo Launchers (2, side nose)', '2D4x10 M.D. high explosive or 1D6x10 M.D. plasma', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 4', '16 mini-torpedoes; 8 per tube', NULL, 'Mini-sub weapon 2. One tube each side of the nose; the sub must face its target. Meant first to help with excavation, and only then for defence.'),
  ('ng-aqua-212-aquapod', 5, 'Mini-Sub: Underwater Excavator/Water Cannon', '5D6 Hit Points per blast to vampires and others harmed by water; not strong enough to knock a person down', 0, '200 ft (61 m)', 'Each blast is one melee attack', '20 blasts on dry land from its 200 gallon (757 liter) tank, unless hosed to a larger supply; effectively unlimited underwater', NULL, 'Mini-sub weapon 3. A heavy water jet under the nose, 360 degrees with a 90 degree arc, that clears sand and debris off wrecks or stirs up a screen of silt. Docked, it fires from the middle of the Aquapod''s belly at targets below only, as when hovering 6-25 ft (1.8 to 7.6 m) over vampires.'),
  ('ng-aqua-212-aquapod', 6, 'Mini-Sub: Extendible Robot Arms (2)', '1D4 M.D. from a swat or a poke; Robot P.S. 25, but they cannot punch', 1, '12 ft (3.6 m) reach', 'Each use is one of the operator''s own attacks, usually the pilot''s or co-pilot''s', NULL, NULL, 'Mini-sub item 4, a salvage tool rather than a weapon. Folded under the nose; each turns any way, backward included, with three-fingered hands fine enough for glass, and carries two small searchlights and a camera. 25 M.D.C. each.'),
  ('ng-amp6-beachcomber-atv', 1, 'Top-Mounted Pulse Laser Turret', '3D6 M.D. per single blast; 1D4x10 M.D. per rapid-fire three-pulse burst', 1, '2,000 ft (610 m)', 'Each single shot or burst is one melee attack', 'Effectively unlimited for the laser; 3,200 rounds for the rail gun', NULL, 'Standard. A low-profile top turret turning 360 degrees with a 30 degree up and down arc. Fuel and battery-powered models carry an NG-202 rail gun (gear row ng-202-rail-gun) instead; the entry prints the rail gun''s payload but not its damage.'),
  ('ng-amp6-beachcomber-atv', 2, 'Grenade Dispenser', 'By grenade type. Smoke: a 50x50 ft (15x15 m) screen from 2 grenades, 100x100 ft (30.5 x 30.5 m) from 4; shooting into or out of it is -10 to strike man-sized targets and -6 against large vehicles', 1, 'About 100 ft (30.5 m) in front of the vehicle', 'Patterns of two or four grenades; whatever is loaded goes at once', '4 smoke grenades', NULL, 'Standard. Not a true launcher: it throws its whole load of 2-4 grenades together for an instant screen. Ordinary grenades can be loaded but fly too wild to aim, useful mostly for driving off attackers up close. Reloaded from outside, best when stopped or crawling.'),
  ('ng-amp6-beachcomber-atv', 3, 'NG-VM8 Mini-Missile/Mini-Torpedo Launcher', 'By mini-missile or mini-torpedo type; 2D4x10 M.D. high explosive or 1D6x10 M.D. plasma mini-torpedoes', 1, 'One mile (1.6 km)', 'One at a time or volleys of two', '8 mini-missiles or mini-torpedoes; a second load is often carried at extra cost and loaded by hand', NULL, 'Optional, 97,500 credits. A simple box launcher in a turret, usually at the back, turning 360 degrees with a 70 degree up and down arc; mini-missiles are the usual load against boats and land vehicles, mini-torpedoes if wanted.'),
  ('ng-su2-bluestorm-submarine', 1, 'Medium Torpedo Tubes (2)', '3D4x10 M.D. high explosive or 2D6x10 M.D. plasma', 1, 'About 10 miles (16 km)', 'One torpedo every four melee rounds (60 seconds), twice as fast with two crewmen at the tubes', '16; eight per tube', NULL, 'Standard. Its heavy anti-ship weapon; shorter ranged than long-range torpedoes, which rarely matters on the Great Lakes.'),
  ('ng-su2-bluestorm-submarine', 2, 'Fore and Aft Blue-Green Laser Turrets (2)', '5D6 M.D. per blast, per gun', 1, '4,000 ft (1,219 m)', 'Each blast is one melee attack; the two cannot fire linked, and each needs its own gunner', 'Effectively unlimited', NULL, 'Standard. Low-profile deck turrets fore and aft, each turning 180 degrees side to side with a 30 degree up and down arc; used on sea monsters when submerged and as deck guns on the surface against pursuers and incoming torpedoes (-1 to strike a torpedo).'),
  ('ng-su2-bluestorm-submarine', 3, 'Towed Anti-Aircraft Pod', 'By missile type', 1, 'By missile type; 1-5 miles (1.6 to 8 km)', 'One at a time or volleys of two', '40 mini-missiles or 8 short-range missiles', NULL, 'Standard. Floated directly above the sub or up to 2 miles (3.2 km) away; surfaced, it switches on a small radar and a camera array for the gunners aboard, who fire, then reel it in to reload. In extremity it can be cut loose to drift, set to empty its whole load at the next target it finds and then fall silent. The pod has 80 M.D.C.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-amp-007-alligator-apc', 'ng-aqua-212-aquapod', 'ng-amp6-beachcomber-atv', 'ng-su2-bluestorm-submarine');
SELECT 'their 44 locations are in' AS assertion, count(*) AS got, 44 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-amp-007-alligator-apc', 'ng-aqua-212-aquapod', 'ng-amp6-beachcomber-atv', 'ng-su2-bluestorm-submarine');
SELECT 'their 15 weapon entries are in' AS assertion, count(*) AS got, 15 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-amp-007-alligator-apc', 'ng-aqua-212-aquapod', 'ng-amp6-beachcomber-atv', 'ng-su2-bluestorm-submarine');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-amp-007-alligator-apc', 'ng-aqua-212-aquapod', 'ng-amp6-beachcomber-atv', 'ng-su2-bluestorm-submarine') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

